import pathlib,json,re,html,subprocess,hashlib,argparse
P=pathlib.Path(__file__).resolve().parent;p=argparse.ArgumentParser();p.add_argument('--site',type=pathlib.Path);a=p.parse_args()
E=json.load(open(P/'candidate-entries.json'))
if a.site:E={e['id']:e for f in (a.site/'dist/data/chapters').glob('*.json') for e in json.load(open(f))['entries']}
blocks=[html.unescape(re.sub('<[^>]+>','',x)) for x in re.findall(r'<pre[^>]*>(.*?)</pre>',E['8']['supplementHtml'],re.S)]
source=[x for x in blocks if 'public final class SSAIntParser' in x];assert len(source)==1
out=P/'evidence/strict-reference';out.mkdir(exist_ok=True);(out/'SSAIntParser.java').write_text(source[0]);(out/'CheckStrict.java').write_text('''public class CheckStrict {public static void main(String[] args){int tests=0;String[] good={"0","-0","+0","2147483647","-2147483648","00000000001","+123","-123"};int[] want={0,0,0,2147483647,-2147483648,1,123,-123};for(int i=0;i<good.length;i++){if(SSAIntParser.parse(good[i])!=want[i])throw new AssertionError(good[i]);tests++;}String[] bad={null,"","+","-","+1x"," 1","1 ","１","2147483648","-2147483649","--1","1.0","0x1","1e2","1_0","+-1"};for(String s:bad){try{SSAIntParser.parse(s);throw new AssertionError("accepted "+s);}catch(NumberFormatException expected){tests++;}}System.out.println("PASS strict reference target: "+tests+" tests");}}''')
c=subprocess.run(['java','-m','jdk.compiler/com.sun.tools.javac.Main','-encoding','UTF-8','-d',str(out),str(out/'SSAIntParser.java'),str(out/'CheckStrict.java')],capture_output=True,text=True);assert c.returncode==0,c.stderr
r=subprocess.run(['java','-cp',str(out),'CheckStrict'],capture_output=True,text=True);assert r.returncode==0,r.stderr
(out/'test.log').write_text(r.stdout+r.stderr);(out/'proof.json').write_text(json.dumps({'status':'passed','target':'entry 8 supplementHtml, SSAIntParser.parse','sourceSha256':hashlib.sha256(source[0].encode()).hexdigest(),'sourceMode':'actual-dist' if a.site else 'candidate enclosing entry; this supplement is unchanged','tests':24,'assertions':'Full int range, optional sign, leading zeros; reject missing digits, non-ASCII digits, partial consumption and out-of-range.'},ensure_ascii=False,indent=2));print(r.stdout)
